    vxd, vyd = state["vx"], state["vy"]
    x, y = pd[0], pd[1]
    ty, w_comp = 1.5, _weight_comp(sandbox)

    # Track total impulse applied to avoid exceeding structural limit
    if "impulse_total" not in MEM.data:
        MEM.data["impulse_total"] = 0.0
    impulse_total = MEM.data["impulse_total"]

    if state["phase"] == "APPROACH":
        front, up, down = sandbox.get_whisker_readings()

