                        fx = 10.0 * (7.0 - x) - 5.0 * vxd
                    fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp
                else:
                    # Move forward
                    if x < 5.0:
                        fx = 15.0
                    else:
                        fx = 10.0 * (7.0 - x) - 5.0 * vxd
                    fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp
            else:
                # Apply forward force to move right
                if x < 5.0:
                    fx = 15.0
                else:
                    fx = 10.0 * (7.0 - x) - 5.0 * vxd
                fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp

        if cfg["act_lo"] <= x <= cfg["act_hi"] and abs(vxd) < 0.5:
            state["phase"] = "UNLOCK"
            state["t"] = 0
