            fy_cmd = 50.0 * (ty - y) - 20.0 * vyd + w_comp
        else:
            fx_cmd = cfg["bfx"] - 1.0
            fy_cmd = 50.0 * (ty - y) - 20.0 * vyd + w_comp

            # Adjust for control lag and speed
            if spd >= 99.0:
                horiz = -1.5 * vx_p
                if horiz > 0:
                    horiz = 0
                fx_cmd += horiz
                fy_cmd -= 1.5 * vy_p

        # Apply force with impulse tracking
        force_magnitude = math.hypot(fx_cmd, fy_cmd)
        impulse = force_magnitude * TIME_STEP
        if impulse_total + impulse > MAX_IMPULSE:
            # Limit force to avoid exceeding impulse limit
            fx_cmd = 0.0
            fy_cmd = 0.0
        else:
            MEM.data["impulse_total"] += impulse

        fx, fy = fx_cmd, fy_cmd
        state["t"] += 1
        if state["t"] > 60:
            state["phase"] = "ESCAPE"
    elif state["phase"] == "ESCAPE":
        fx, fy = 15.0, 50.0 * (ty - y) - 20.0 * vyd + w_comp
        if x > _exit_x_min(sandbox) + 2.5:
            state["phase"] = "HOLD"
